head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.btn_search_onclick = function() {
    tac1.getWindow().scwin.search();
};
scwin.checkVal = function() {
    var ss = WebSquare.wUnit.getDomById($p.id + 'tac1_contents_content1_body_'+$p.id+'tac1_contents_content1_body_wq_processMsgComp');
    var top = parseInt(ss.style.top) < 150;
    var left = parseInt(ss.style.left) < 220;
    return top && left;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('tac1_contents_content1_body_trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
